"place/creche-pop-e-poppa-vaulruz-vaulruz/ageTo":{"en":"aadb9bec61db15750977ab78dcf674674507b74f3219ac97ed55900c1a4eb129","text":"Jusqu’à l’entrée à l’école"},
"place/creche-pop-e-poppa-vaulruz-vaulruz/hours":{"en":"65be172bdf8d72020bc83b248f5c04b9d4f5a20fb25587ad32921a4445375787","text":"Lun–ven 06:30–18:00"},
