"place/kindertagesstatte-schmitten-schmitten/pedagogy":{"en":"e6c265f8ab0b32a0a765b88ae5525388f1e82581f93f1cdd5ee89ab9f313f135","text":"Jeu et activités adaptés à l’âge, personnes de référence fiables, respect de chaque enfant comme individu et règles claires."},
