"place/kita-sandkasten-ried-bei-kerzers-ried-bei-kerzers/subsidised":{"en":"3fe8e6cecd894e52fc53b6b6d6bafa07c9adeec3cc773945d71be56392f29a6d","text":"La commune de Ried indique avoir un accord avec Kita Sandkasten depuis le 1er janvier 2023."},
